# -*- coding: utf-8 -*-
import random

JAPANESE_TRIVIA = [{'title': '🚦 綠燈為什麼日本人叫「青信號」？', 'story': '古代日語原始只有四個顏色詞（黑、白、赤、青）。「青」涵蓋了現代的藍色與綠色，因此日本的綠燈、青菜、青蘋果在日語裡通通都叫做「青 (あお)」喔！'}, {'title': '🍻 日本居酒屋喊「乾杯」真的要喝光嗎？', 'story': '不用！在台灣「乾杯」常被當成杯底朝天乾掉；但在日本居酒屋說「乾杯」，純粹是「碰杯祝福、祝大家健康」的儀式，輕輕抿一口即可，喝光反而可能會被當成太心急呢！'}, {'title': '💪 「大丈夫」在日語裡根本不是男子漢？', 'story': '中文的「大丈夫」指頂天立地的豪邁男子；但在日語裡「大丈夫 (だいじょうぶ)」意思是「沒問題、不要緊、沒關係」，甚至店員問你要不要袋子時說大丈夫，意思就是「不用了，謝謝」！'}, {'title': '🐴 「馬鹿」這個笨蛋詞從哪裡來的？', 'story': '源自秦朝趙高的成語「指鹿為馬」，原本形容是非不分，傳入日本後演變為指人愚蠢。不過在關西（如大阪），朋友間說「アホ (Aho)」反而比「バカ」更親切自然！'}, {'title': '🙇 日本人的萬能神詞「すみません」到底有多少意思？', 'story': '日本人一天平均要說好幾十次！它既是「對不起 (抱歉)」，也是在電車借過的「不好意思」，在餐廳叫店員是「Excuse me」，別人幫你開門時更是「謝謝 (不好意思讓您費心了)」！'}, {'title': '🍙 便利商店的「おにぎり」和「おむすび」有何差別？', 'story': '三角飯糰通常叫「おにぎり」(握り)，而古時候將飯糰捏成神山三角錐形狀用以祈福、結緣，被稱為「おむすび」(結び)。據說吃了おむすび還能結交良緣喔！'}, {'title': '🍜 吃拉麵為什麼發出超大「簌簌」吸麵聲才禮貌？', 'story': '日本人吃拉麵時大力吸麵（啜る / susuru），並不是沒禮貌，而是藉由空氣混合湯汁與麵條，讓香氣在鼻腔徹底綻放！而且對拉麵師傅來說，吸麵聲越大代表「太好吃了」的最高讚美！'}, {'title': '❤️ 「愛人」在日本千萬不能隨便亂介紹！', 'story': '在中文裡「愛人」是指合法的先生或太太；但日文中的「愛人 (あいじん)」專指「情婦、小三、婚外情對象」！如果在日本指著另一半說「這是我的愛人」，大家下巴會掉下來喔！'}, {'title': '✉️ 「手紙」在日本竟然是信件？', 'story': '在日語中「手紙 (てがみ)」是書信、信函的意思！如果您在廁所裡著急找手紙，日本人只會拿信紙給您。衛生紙一定要說「トイレットペーパー (Toilet Paper)」或「ティッシュ」喔！'}, {'title': '🍀 日本人為什麼最喜歡「8」這個數字？', 'story': '日本漢字「八」的形狀是上面小、下面開闊，象徵「末広がり (すえひろがり)」，也就是未來的運勢就像扇子展開一樣步步高升、越來越發達！'}, {'title': '🍣 迴轉壽司店的茶為什麼叫「あがり」？', 'story': '「あがり」源自花街歌舞伎文化，代表「演出結束 (上がり) 給客人的收尾熱茶」。在壽司店用這個行話跟師傅要熱茶，師傅會覺得您超級內行！'}, {'title': '🍱 日本冷便當文化背後的貼心之處', 'story': '日本人從小習慣吃冷便當，不是因為微波爐不普及，而是日本文化講究「不要給別人添麻煩」——熱便當會有濃郁氣味散發到教室或電車裡，冷便當則味道清淡內斂！'}, {'title': '🐦 烏鴉在日本竟然是「神鳥吉祥物」？', 'story': '在華人文化中烏鴉常被視為不祥；但在日本神話中，擁有三隻腳的「八咫烏 (やたがらす)」是引導初代天皇的神鳥，甚至日本國家足球隊的隊徽上就是八咫烏！'}, {'title': '☕ 日本的「純喫茶」到底有多純？', 'story': '昭和時代日本有許多陪酒營業的「特殊喫茶」，因此為了強調自己是「單純只賣咖啡甜點、不提供酒精與風俗娛樂的清白店家」，才掛上「純喫茶 (じゅんきっさ)」的招牌！'}, {'title': '👘 「いただきます」不只是我開動了，而是感謝萬物生命！', 'story': '這句話字面意思是「頂戴 (頂きます)」，也就是用頭頂恭敬地承接。日本人飯前說這句話，除了感謝廚師，更是感謝食材為了滋養我們的生命而奉獻自己的生命！'}]

def get_random_trivia() -> dict:
    return random.choice(JAPANESE_TRIVIA)
